def dune_catalog_source(snapshot: dict[str, Any]) -> tuple[str, str, str, str]:
    """Describe the selected Dune result without promoting cached metadata to data."""
    section = snapshot.get("dune")
    if not isinstance(section, dict):
        return (
            "Dune registered query",
            "No Dune query state recorded in this snapshot",
            "No source observation",
            "Unavailable",
        )
    current = section.get("available") is True
    last_known_good = section.get("last_known_good")
    record = section if current else (
        last_known_good if isinstance(last_known_good, dict) else {}
    )
    aggregates = record.get("aggregates") \
        if isinstance(record.get("aggregates"), dict) else {}
    has_daily_values = any(is_number(aggregates.get(key)) for key in (
        "fee_payers_latest",
        "dex_volume_total_latest_usd",
        "xstocks_dex_volume_latest_usd",
        "xstocks_dex_trade_legs",
        "xstocks_dex_priced_trade_legs",
        "transaction_fees_latest_sol",
    ))
    query_id = record.get("query_id") or section.get("query_id")
    source = f"Dune query {query_id}" if query_id else "Dune registered query"
    ended_at = record.get("execution_ended_at")
    freshness = timestamp_label(ended_at) if ended_at else "No source observation"
    if current:
        return (
            source,
            "Current registered-query result with daily aggregates"
            if has_daily_values else "Current result metadata recorded; daily aggregates unavailable",
            freshness,
            "Recorded" if has_daily_values else "Unavailable",
        )
    reason = str(section.get("reason") or "Current Dune query unavailable")
    if has_daily_values:
        return (
            source,
            f"Current query unavailable: {reason} · cached last-known-good daily aggregates",
            freshness,
            "Stale · last-known-good",
        )
    paused = any(word in reason.lower() for word in ("allowance", "budget", "credit"))
    state = "Current result read paused" if paused else "Current query unavailable"
    coverage = (
        f"{state}: {reason} · last-known-good execution metadata only; "
        "daily aggregate values unavailable in this snapshot"
        if record else f"{state}: {reason} · no last-known-good result recorded"
    )
    return source, coverage, freshness, "Unavailable"


def feature_catalog_source(snapshot: dict[str, Any]) -> tuple[str, str, str, str]:
    """Describe the bounded finalized feature-account inspection."""
    section = snapshot.get("feature_activation")
    if not isinstance(section, dict):
        return (
            "getMultipleAccounts(finalized) + pinned Agave feature set",
            "No selected feature-account inspection recorded",
            "No source observation",
            "Unavailable",
        )
    numerator = section.get("coverage_numerator")
    denominator = section.get("coverage_denominator")
    activated = section.get("activated_feature_count")
    coverage = (
        f"{fmt(numerator)} / {fmt(denominator)} pinned feature accounts inspected · "
        f"{fmt(activated)} decoded activated states · selected set, not a complete upgrade inventory"
    )
    freshness = timestamp_label(section.get("observed_at")) \
        if section.get("observed_at") else "No source observation"
    if section.get("available") is not True:
        return (
            "getMultipleAccounts(finalized) + pinned Agave feature set",
            str(section.get("reason") or "Selected feature-account inspection unavailable"),
            freshness,
            "Unavailable",
        )
    status = "Recorded" if section.get("coverage_complete") is True else "Partial"
    return (
        "getMultipleAccounts(finalized) + pinned Agave feature set",
        coverage,
        freshness,
        status,
    )


CLUSTER_SOFTWARE_METRICS = tuple("cluster_software_" + field for field in (
    "observed_node_count", "version_reported_node_count", "unknown_version_node_count",
    "other_reported_version_node_count",
))


def cluster_software_catalog(snapshot):
    section = snapshot.get("cluster_software") or {}
    if section.get("available") is not True:
        return "Source unavailable", "No usable version census", "Unavailable"
    return (f"{fmt(section['observed_node_count'])} observed {'node' if section['observed_node_count'] == 1 else 'nodes'} · {fmt(section['unknown_version_node_count'])} {'node' if section['unknown_version_node_count'] == 1 else 'nodes'} with unknown version",
            timestamp_label(section.get("observed_at")), "Recorded")


def render_cluster_software(snapshot, context, observation_indexes=None) -> str:
    section = snapshot.get("cluster_software")
    if not isinstance(section, dict):
        return ""
    stamp = str(snapshot.get("collected_at"))
    binding = summary_observation_attribute(observation_indexes, stamp, CLUSTER_SOFTWARE_METRICS)
    if section.get("available") is not True:
        body = "<p>Cluster-node version evidence is unavailable. No adoption share is inferred.</p>"
    else:
        total = section["observed_node_count"]
        rows = []
        for row in section.get("versions", []):
            row_binding = ""
            if observation_indexes is not None:
                record = observation_indexes['subject'].get((
                    'cluster_software_version_nodes', row['version'], section.get('observed_at'), stamp))
                if record is None:
                    raise ValueError("cluster version has no public observation")
                total_record = observation_indexes['summary'][(CLUSTER_SOFTWARE_METRICS[0], stamp)]
                row_binding = observation_ids_attribute([record['observation_id'], total_record['observation_id']])
            label = html.escape(row['version'])
            count = row['node_count']
            rows.append(f"<li{row_binding}><div><span>{label}</span><strong>{fmt(count)} {'node' if count == 1 else 'nodes'}</strong></div>"
                        f"<meter min='0' max='{total}' value='{count}' aria-label='Nodes reporting version {html.escape(row['version'], quote=True)}'>{count} of {total}</meter></li>")
        for field, label in (("unknown_version_node_count", "Unknown version"),
                             ("other_reported_version_node_count", "Other reported versions")):
            count = section[field]
            rows.append(f"<li{binding}><div><span>{label}</span><strong>{fmt(count)} {'node' if count == 1 else 'nodes'}</strong></div>"
                        f"<meter min='0' max='{total}' value='{count}' aria-label='{label}'>{count} of {total}</meter></li>")
        body = (f"<p{binding}>{fmt(total)} {'node' if total == 1 else 'nodes'} observed; {fmt(section['version_reported_node_count'])} report a version. "
                f"Observed {html.escape(timestamp_label(section.get('observed_at')))}.</p>"
                f"<ul class='cluster-version-bars'>{''.join(rows)}</ul>")
    return (f"<details class='report-coverage cluster-software' id='{context}-cluster-software'>"
            "<summary>Cluster-node software versions</summary>"
            "<p>Exact version strings from nodes known to the queried RPC endpoint. Unweighted node counts; "
            "this is not validator-client or stake adoption, and does not identify Firedancer. Unknown versions remain visible.</p>"
            + body + "<p><a href='https://solana.com/docs/rpc/http/getclusternodes' target='_blank' rel='noopener noreferrer'>getClusterNodes methodology</a></p></details>")


def render_feature_activation(snapshot, context, observation_indexes=None) -> str:
    """Show source-native feature account state without inferring proposal activation."""
    section = snapshot.get('feature_activation')
    if not isinstance(section, dict):
        return ''
    prefix = 'mobile' if context == 'mobile' else 'desktop'
    source = section.get('source', {})
    metadata = section.get('metadata', {})
    snapshot_at = str(snapshot.get('collected_at'))
    summary_binding = summary_observation_attribute(
        observation_indexes, snapshot_at,
        ('feature_activation_coverage_numerator', 'feature_activation_coverage_denominator',
         'feature_activated_count', 'feature_rpc_context_slot'),
    )
    rows = []
    labels = {'activated': 'Activated', 'pending': 'Pending',
              'account_absent': 'Account absent', 'unavailable': 'Unavailable'}
    for feature in section.get('features', []):
        binding = ''
        if observation_indexes is not None:
            records = [record for key, record in observation_indexes['subject'].items()
                       if key[0] in ('feature_activation_state', 'feature_activated_at_slot')
                       and key[1] == feature.get('key') and key[-1] == snapshot_at]
            if len(records) != 2:
                raise ValueError(f"feature account has no complete public observation: {feature.get('key')}")
            binding = observation_ids_attribute([record['observation_id'] for record in records])
        state = feature.get('state')
        if state == 'activated':
            evidence = f"Activation slot {fmt_id(feature.get('activated_at_slot'))}"
        elif state == 'pending':
            evidence = 'Valid feature account without an activation slot.'
        elif state == 'account_absent':
            evidence = 'No account returned at this finalized context; this does not establish activation history.'
        else:
            evidence = str(feature.get('reason') or 'No usable account observation.')
        rows.append(
            f"<tr data-feature-key='{html.escape(str(feature.get('key')), quote=True)}'{binding}>"
            f"<th scope='row'>{html.escape(str(feature.get('title') or feature.get('key')))}"
            f"<small>{html.escape(str(feature.get('simd') or 'Protocol feature'))}</small></th>"
            f"<td><strong>{labels.get(state, 'Unavailable')}</strong><span>{html.escape(evidence)}</span>"
            f"<small><code>{html.escape(str(feature.get('address') or 'Address unavailable'))}</code></small></td></tr>"
        )
    url = safe_external_href(metadata.get('source_url'))
    reference = (f"<a href='{html.escape(url, quote=True)}' target='_blank' rel='noopener noreferrer'>Pinned Agave definitions</a>"
                 if url else 'Pinned source definitions unavailable')
    checked = f"{fmt(section.get('coverage_numerator'))} of {fmt(section.get('coverage_denominator'))} selected accounts observed"
    return (
        f"<details class='report-coverage feature-activation' id='{prefix}-feature-activation'>"
        "<summary>On-chain feature activation</summary>"
        f"<p{summary_binding}>{html.escape(checked)} · {html.escape(development_time_label(section.get('observed_at')))}. "
        f"Finalized RPC context slot {html.escape(fmt_id(source.get('rpc_context_slot')))}.</p>"
        "<p>This watch covers selected Alpenglow, slot-timing and rent gates. Account state is separate from "
        "proposal acceptance, software release, and a full cluster software census. "
        f"{reference}.</p><div class='table-wrap'><table>"
        "<caption class='visually-hidden'>Selected protocol feature accounts and activation evidence</caption>"
        "<thead><tr><th scope='col'>Feature</th><th scope='col'>Recorded account evidence</th></tr></thead>"
        f"<tbody>{''.join(rows)}</tbody></table></div></details>"
    )


